{"content": "import fitz

doc = fitz.open("workspace/input/input.pdf")
page = doc[0]
print("Page rect:", page.rect)

targets = ["STUDENT NAME", "STUDENT PID#", "UCSD E-MAIL", "DATE OF BIRTH",
           "PHONE NUMBER", "Reason for appeal", "Applicant", "signature", "Date",
           "Yaya", "A88888888", "jiang@gmail.com", "2003/06/18"]
for t in targets:
    rects = page.search_for(t)
    for r in rects:
        print(f"{t!r}: {r}")

print("\n--- drawings (lines) ---")
for d in page.get_drawings():
    if d["type"] in ("s", "f", "fs"):
        for item in d["items"]:
            if item[0] == "l":
                p1, p2 = item[1], item[2]
                print(f"line: ({p1.x:.1f},{p1.y:.1f}) -> ({p2.x:.1f},{p2.y:.1f})")
            elif item[0] == "re":
                print(f"rect: {item[1]}")

print("\n--- text dict blocks with positions ---")
d = page.get_text("dict")
for b in d["blocks"]:
    if b["type"] != 0:
        continue
    for l in b["lines"]:
        for s in l["spans"]:
            print(f"span: {s['text']!r} bbox={s['bbox']} font={s['font']} size={s['size']:.1f}")
